-- Seed généré depuis data/catalog.json (catalogue réel WooCommerce)

-- Catégories (parents avant enfants)
on conflict (slug) do update set name=excluded.name, parent=excluded.parent, icon=excluded.icon, description=excluded.description;

-- Produits
on conflict (slug) do update set name=excluded.name, description=excluded.description, price=excluded.price, category=excluded.category, image=excluded.image, on_sale=excluded.on_sale, in_stock=excluded.in_stock;
